// Private offline UI fixture: no backend, account, provider or business effect.
window.fetch=async()=>{throw new Error('Offline effort fixture forbids network');};
window.WebSocket=class{constructor(){throw new Error('Offline effort fixture forbids WebSocket');}} as unknown as typeof WebSocket;
window.XMLHttpRequest=class{constructor(){throw new Error('Offline effort fixture forbids XHR');}} as unknown as typeof XMLHttpRequest;
navigator.sendBeacon=()=>false;

export * from '../../scripts/live-drive/harness/operations-release-mount/stubs';
import {useCallback,useMemo,useSyncExternalStore} from 'react';
import {ACTOR,TENANT,supabase as originalPorts} from '../../scripts/live-drive/harness/operations-release-mount/stubs';
const mode=new URLSearchParams(location.search).get('effortState')??'ready';
const key='offline-exp05-effort-source';
const initial={id:'ef050000-0000-4000-8000-00000000a001',tenant_id:TENANT,user_id:ACTOR,title:'Prepare the client delivery review',description:'Neutral offline workflow fixture. No customer or provider action.',status:'pending',due_date:null,updated_at:'2026-10-29T12:00:00.123456Z',created_at:'2026-10-28T12:00:00Z',deal_id:null,biz_id:null,recorded_priority:'P1',estimated_minutes:15};
let task=JSON.parse(sessionStorage.getItem(key)??'null')??initial;
const listeners=new Set<()=>void>();
const subscribe=(notify:()=>void)=>{listeners.add(notify);return()=>{listeners.delete(notify);};};
const snapshot=()=>task;
export function useOperationsCrmWork(){
 const record=useSyncExternalStore(subscribe,snapshot);
 const tasks=useMemo(()=>[record],[record]);
 const refresh=useCallback(async()=>[task],[]);
 const readTask=useCallback(async(id:string)=>({status:'available',found:id===task.id,task:id===task.id?task:null}),[]);
 return{tasks,loading:false,error:mode==='unavailable'?'Offline fixture source refused':null,forbidden:false,hasMore:false,refresh,readTask};
}
export const supabase={...originalPorts,
 rpc:(name:string,args:Record<string,unknown>={})=>name==='is_tenant_admin'?Promise.resolve({data:mode!=='denied',error:null}):originalPorts.rpc(name,args),
 functions:{invoke:async(name:string,{body}:{body:Record<string,any>})=>{
  if(name!=='crm-command')return{data:null,error:{message:'Offline fixture refuses unimplemented transport'}};
  if(mode==='refused')return{data:{ok:false,outcome:'refused'},error:null};
  const operation=body.command;
  if(body.expected_tenant_id!==TENANT||operation.task_id!==task.id||operation.action!=='task.update'||Object.keys(operation.patch??{}).join(',')!=='estimated_minutes')throw Error('Offline fixture unexpected command');
  const cacheKey='offline-effort-result:'+body.idempotency_key,cached=sessionStorage.getItem(cacheKey);
  if(cached)return{data:JSON.parse(cached),error:null};
  if(!body.approved_fingerprint)return{data:{outcome:'approval_required',fingerprint:'offline-effort-fingerprint',summary:'Offline Trust response · review the exact Task change below.'},error:null};
  if(body.approved_fingerprint!=='offline-effort-fingerprint'||operation.expected_updated_at!==task.updated_at)return{data:{ok:false,outcome:'refused'},error:null};
  const minutes=operation.patch.estimated_minutes;
  if(minutes!==null&&(!Number.isSafeInteger(minutes)||minutes<0||minutes>2147483647))return{data:{ok:false,outcome:'refused'},error:null};
  task={...task,estimated_minutes:minutes,updated_at:new Date().toISOString()};
  sessionStorage.setItem(key,JSON.stringify(task));for(const notify of listeners)notify();
  const result={ok:true,readback:{id:task.id,metadata:minutes===null?{fixture_other:'preserved'}:{fixture_other:'preserved',estimated_minutes:minutes},external_effect:false,notification_sent:false,updated_at:task.updated_at}};
  sessionStorage.setItem(cacheKey,JSON.stringify(result));
  return mode==='unknown'?{data:{outcome_unknown:true},error:null}:{data:result,error:null};
 }},
};

import path from 'node:path';
import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import base from '../../scripts/live-drive/harness/operations-release-mount/vite.config';
const root=import.meta.dirname,repo=path.resolve(root,'../..'),ports=path.join(root,'ports.ts');
const sha=(p:string)=>createHash('sha256').update(readFileSync(p)).digest('hex');
export default {...base,root,envDir:root,publicDir:path.join(repo,'public'),cacheDir:path.join(root,'cache'),
 resolve:{...base.resolve,alias:base.resolve.alias.map(entry=>({...entry,replacement:entry.replacement.endsWith('stubs.ts')?ports:entry.replacement}))},
 build:{outDir:path.join(root,'dist'),emptyOutDir:false},
 plugins:[...base.plugins,{name:'private-effort-source-manifest',generateBundle(){const repoPosix=repo.replaceAll('\\','/');const inputs=[...this.getModuleIds()].filter(p=>p.replaceAll('\\','/').startsWith(repoPosix+'/src/')&&!p.includes('?')).map(p=>({path:path.relative(repo,p).replaceAll('\\','/'),sha256:sha(p)}));if(inputs.length<4)throw Error('No authoritative product input manifest');writeFileSync(path.join(root,'source-manifest.json'),JSON.stringify({boundary:'OFFLINE FULL OPERATIONS MOUNT; SYNTHETIC AUTH/TASK/EXECUTION PORTS; NO AUTHENTICATED OR PRODUCTION EFFECT PROOF',inputs},null,2));}}],
};

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
const root=path.resolve(import.meta.dirname,'dist');
const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://localhost');const wanted=path.resolve(root,'.'+decodeURIComponent(url.pathname));if(!wanted.startsWith(root+path.sep)){res.writeHead(403).end();return;}const file=fs.existsSync(wanted)&&fs.statSync(wanted).isFile()?wanted:path.join(root,'index.html');const ext=path.extname(file);res.setHeader('Content-Type',({'.html':'text/html','.js':'text/javascript','.css':'text/css','.woff2':'font/woff2','.svg':'image/svg+xml'})[ext]??'application/octet-stream');res.setHeader('Cache-Control','no-store');res.end(fs.readFileSync(file));});
server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({origin:'http://127.0.0.1:'+server.address().port,boundary:'offline synthetic full Operations mount'})));
